import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 8 Trading standards","description":"学习 情态动词的被动结构，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 8 Trading standards","description":"学习 情态动词的被动结构，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 情态动词的被动结构，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 7 Bats","link":"/life/english/new-concept/book-4/unit-01/lesson-007"},"next":{"text":"第四册：流利英语 · Lesson 9 Royal espionage","link":"/life/english/new-concept/book-4/unit-02/lesson-009"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 7 Bats","link":"/life/english/new-concept/book-4/unit-01/lesson-007"},"next":{"text":"第四册：流利英语 · Lesson 9 Royal espionage","link":"/life/english/new-concept/book-4/unit-02/lesson-009"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-008.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-008.md"}'),s={name:"life/english/new-concept/book-4/unit-01/lesson-008.md"};function i(l,e,r,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-8-trading-standards" tabindex="-1">第四册：流利英语 · Lesson 8 Trading standards <a class="header-anchor" href="#第四册-流利英语-·-lesson-8-trading-standards" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 8 Trading standards&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕不同地区的商品标准与重复检验如何影响贸易，学习区分产品安全目标、认证程序和谈判分歧。不要把历史贸易争议当作当前规则；伴读用虚构工作坊训练要求表达。重点使用条件明确的被动结构，说明产品需要接受什么检查、由谁负责，以及某条要求适用于什么范围。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>standard</td><td>/ˈstændəd/</td><td>n.</td><td>标准</td><td>meet a standard</td></tr><tr><td>defect</td><td>/ˈdiːfekt/</td><td>n.</td><td>缺陷</td><td>a manufacturing defect</td></tr><tr><td>label</td><td>/ˈleɪbəl/</td><td>n.</td><td>标签</td><td>a product label</td></tr><tr><td>inspection</td><td>/ɪnˈspekʃən/</td><td>n.</td><td>检查</td><td>a final inspection</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>comply with — 遵守某标准或要求</li><li>fit for purpose — 适合预定用途</li></ul><h2 id="语法讲解-情态动词的被动结构" tabindex="-1">语法讲解：情态动词的被动结构 <a class="header-anchor" href="#语法讲解-情态动词的被动结构" aria-label="Permalink to &quot;语法讲解：情态动词的被动结构&quot;">​</a></h2><p>must be tested 表示必须被检测，should be tested 通常表示建议或较弱义务，may be tested 表示许可或可能；具体含义取决于语境。结构为情态动词 + be + 过去分词，不能省略 be。标准文件常用被动突出对象，但应在必要时加 by 短语说明责任人。课堂中的 must 只是练习设定的要求，不能据此推断现实法律规定。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Under our workshop rules, every sample must be checked before it is packed.</p></blockquote><p>按照我们工作坊的规定，每个样品都必须在包装前接受检查。</p><p>must be checked 是情态被动；before 引导时间从句；under…限定规则的适用范围。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>every sample must checked 缺少 be；必须写 must be checked。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照读 must be checked 与 must check，听辨 be 的存在；录音后确认没有吞掉被动结构中的 be。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Each label must be checked before packing. Damaged boxes should be replaced. The supervisor must record the final inspection.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为虚构工作坊写三句包装检查说明：检查对象、缺陷处理、记录责任。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>前两句突出对象，末句主动交代负责人；must 与 should 区分要求强度。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：The labels must ___ replaced before delivery.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 情态动词被动结构需要 be。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>将主动句 Our team should inspect the boxes. 改为被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The boxes should be inspected by our team.</p><p><strong>解析：</strong> 宾语升为主语，should 后使用 be inspected。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>示例中的要求适用于哪里？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 该工作坊。</p><p><strong>解析：</strong> Under our workshop rules 限定范围，并未声称是法律。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词的被动结构。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-007">上一课</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-009">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(s,[["render",i]]);export{u as __pageData,b as default};
